#include <stdio.h>

/* 25x25 membrane, edges clamped to zero (a drumhead in its rim) */
double before[25][25];
double now[25][25];
double next[25][25];
int N = 25;

int main() {
    for (int y = 0; y < N; y++)
        for (int x = 0; x < N; x++) { before[y][x] = 0; now[y][x] = 0; next[y][x] = 0; }

    /* pluck: a smooth bump off-centre, at rest (before = now) */
    for (int y = 1; y < N - 1; y++) {
        for (int x = 1; x < N - 1; x++) {
            double dx = (x - 8.0) / 3.0;
            double dy = (y - 9.0) / 3.0;
            double r2 = dx * dx + dy * dy;
            if (r2 < 9.0) {
                double v = 1.0 - r2 / 9.0;
                now[y][x] = v * v;
                before[y][x] = now[y][x];
            }
        }
    }

    double c2 = 0.25;   /* courant number squared - stable below 0.5 */
    int steps = 90;
    int emit_every = 3;

    printf("__NB_SET__ {\"key\":\"membrane\",\"value\":{\"n\":%d,\"frames\":[", N);
    int emitted = 0;
    for (int s = 0; s <= steps; s++) {
        if (s % emit_every == 0) {
            if (emitted > 0) printf(",");
            printf("\"");
            for (int y = 0; y < N; y++) {
                for (int x = 0; x < N; x++) {
                    /* quantise -1..1 to 00..ff */
                    int q = (int)((now[y][x] + 1.0) * 127.5);
                    if (q < 0) q = 0;
                    if (q > 255) q = 255;
                    printf("%02x", q);
                }
            }
            printf("\"");
            emitted++;
        }
        for (int y = 1; y < N - 1; y++) {
            for (int x = 1; x < N - 1; x++) {
                double lap = now[y - 1][x] + now[y + 1][x] + now[y][x - 1] + now[y][x + 1]
                           - 4.0 * now[y][x];
                next[y][x] = 2.0 * now[y][x] - before[y][x] + c2 * lap;
            }
        }
        for (int y = 1; y < N - 1; y++) {
            for (int x = 1; x < N - 1; x++) {
                before[y][x] = now[y][x];
                now[y][x] = next[y][x];
            }
        }
    }
    printf("]}}\n");
    printf("simulated %d steps, emitted %d frames of %dx%d\n", steps, emitted, N, N);

    /* energy sanity: the membrane should still be moving, not exploded */
    double maxu = 0;
    for (int y = 0; y < N; y++)
        for (int x = 0; x < N; x++)
            if (now[y][x] > maxu || -now[y][x] > maxu)
                maxu = now[y][x] > 0 ? now[y][x] : -now[y][x];
    printf("final max |u| = %.3f (started at 1.0 - bounded means stable)\n", maxu);
    return 0;
}
